function wrap(text, font, size, width) {
	const words = text.replace(/\s+/g, " ").split(" ");
	const lines = [];
	let line = "";
	words.forEach((word) => {
		const candidate = line ? `${line} ${word}` : word;
		if (font.widthOfTextAtSize(candidate, size) <= width) line = candidate;
		else {
			if (line) lines.push(line);
			line = word;
		}
	});
	if (line) lines.push(line);
	return lines;
}
