function paragraph(page, text, y, font, size = 9, color = navy, width = 500) {
	const lines = wrap(text, font, size, width);
	lines.forEach((line, index) => page.drawText(line, {
		x: 48,
		y: y - index * 14,
		size,
		font,
		color
	}));
	return y - lines.length * 14;
}
